  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Prihvaćam licenciju EUPL 1.2 i pročitao/la sam koje podatke OciDeck pohranjuje.',
  'Lees de volledige licentie': 'Pročitaj cijelu licenciju',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck je slobodan softver pod licencijom EUPL 1.2. Prije nego što započnete, molimo vas da prihvatite licenciju. U nastavku možete pročitati i koje podatke OciDeck pohranjuje na ovom uređaju te kada nešto napušta vaš uređaj.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck ne prikuplja statistiku i ne šalje ništa sam od sebe. Prema zadanim postavkama sve ostaje na ovom uređaju. Podaci napuštaju ovaj uređaj samo ako to sami odaberete:\n\n•  Nextcloud/WebDAV: kada se povežete s poslužiteljem, vaše korisničko ime i lozinka se pohranjuju (lozinka sigurno u sustavskom lancu ključeva), a prezentacije koje otvarate ili spremate šalju se na taj poslužitelj.\n•  Otvaranje putem URL-a: OciDeck dohvaća datoteku s adrese koju unesete.\n•  Mrežni mediji (isključeno prema zadanim postavkama): kada je omogućeno, OciDeck učitava slike i videozapise s adresa u vašim slajdovima.\n•  Vanjske poveznice (poput mrežne licencije) otvaraju se u vašem pregledniku.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck se pruža pod licencijom European Union Public Licence v1.2. Pristankom prihvaćate ovu licenciju. OciDeck smijete koristiti, kopirati, mijenjati i distribuirati pod uvjetima licencije EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Kako bi radio i sačuvao vaš rad, OciDeck pohranjuje podatke lokalno na ovom uređaju:\n\n•  Vaše postavke i preferencije (jezik, mape, profili stila i izgleda, nedavne datoteke).\n•  Vaše materijale za prezentaciju: prezentacije koje spremate, automatske kopije za oporavak i privitke poput opisa slika.\n•  Ovaj izbor pristanka.\n\nOvo možete ukloniti brisanjem datoteka ili poništavanjem postavki.',
