  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Certifikat ovog poslužitelja nije pouzdan. Na samostalno hostanom poslužitelja možete ga pregledati i označiti pouzdanim u Postavke → Pohrana.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Certifikat ovog forge nije pouzdan. Na samostalno hostanom forge možete ga pregledati i označiti pouzdanim u Postavke → Pohrana.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Certifikat ovog endpoint nije pouzdan. Na samostalno hostanom endpoint možete ga pregledati i označiti pouzdanim u Postavke → Pohrana.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Certifikat forge nije pouzdan — samopotpisan, istekao ili izdan na drugo ime.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Certifikat endpoint nije pouzdan — samopotpisan, istekao ili izdan na drugo ime.',
  'creditcardnummer': 'broj kreditne kartice',
  'beveiligingscode van een creditcard': 'sigurnosni kod kartice (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'podaci u bilješkama izlagača — nevidljivi na slajdu, ali su u izvozu',
  'Certificaat vertrouwen?': 'Vjerovati ovom certifikatu?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Certifikat ovog poslužitelja nije potpisan od priznatog izdavatelja. To je uobičajeno kod samostalno hostanog poslužitelja, ali tako izgleda i presretnuta veza.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Usporedite otisak ispod s onim što prikazuje vaš poslužitelj. Ako se podudaraju, razgovarate s pravim strojem.',
  'Uitgegeven aan': 'Izdano za',
  'Uitgegeven door': 'Izdao',
  'Geldig tot': 'Vrijedi do',
  'Vingerafdruk (SHA-256)': 'Otisak (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Pouzdanim se smatra samo ovaj certifikat. Ako ga poslužitelj kasnije zamijeni, OciDeck će pitati ponovno.',
  'Vertrouwen': 'Vjeruj',
  'Certificaat bekijken': 'Prikaži certifikat',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Mjesta na kojima čuvaš i pretražuješ svoje prezentacije — mape na ovom računalu, WebDAV poslužitelji, S3 spremnici i git repozitoriji izmiješani. Povuci ih u redoslijed koji želiš: najgornji svoje vrste vrijedi kao zadani.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3 pohrana: kada se povežeš sa spremnikom, spremaju se krajnja točka, naziv spremnika i tvoj pristupni ključ (tajni ključ sigurno u svežnju ključeva tvojeg sustava), a prezentacije koje otvaraš ili spremaš šalju se toj usluzi pohrane.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git pohrana: kada se povežeš s repozitorijem, sprema se tvoj pristupni token (sigurno u svežnju ključeva tvojeg sustava), a prezentacije koje spremaš šalju se tom poslužitelju kao commitovi. Radna kopija repozitorija ostaje nešifrirana na ovom uređaju.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Za jezik ove prezentacije nedostaju nazivi bolesti. Vjera, političko uvjerenje i sindikalni pojmovi se prepoznaju, a uzorci s kontrolnom znamenkom (OIB, IBAN, putovnica) uvijek rade — ali ne računajte na to da će dijagnoza biti pronađena.',
  'niet getest': 'nije testirano',
  'Werkte op': 'Radilo je',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Prijavljeni ste, ali ovdje nemate pristup. Lozinka nije problem — zatražite od administratora prava na ovu mapu.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Vaš token je valjan, ali ovo ne smije. Dajte mu više prava ili pričekajte ako forge nameće ograničenje.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Token je valjan, ali ovo ne smije — dajte mu više prava na repozitorij.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Prijavljeni ste, ali bez pristupa — lozinka nije problem. Zatražite prava na ovu mapu.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Ovo izgleda kao potpuni DAV URL. Kod Nextclouda OciDeck sam izvodi tu putanju — ovdje pripada samo poslužitelj.',
  'Overnemen': 'Primijeni',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV nije (dobro) postavljen — provjerite podatke poslužitelja u Postavke → Pohrana.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git repozitorij nije (dobro) postavljen — provjerite poslužitelj, vlasnika i repozitorij u Postavke → Pohrana.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Naziv poslužitelja forgea ne postoji ili se ne može pronaći. Provjerite ima li u URL-u poslužitelja tipfelera.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Ovaj forge ima privatnu ili LAN adresu. Označite ga kao pouzdan interni u Postavke → Pohrana.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge nije dostupan — provjerite vezu i URL poslužitelja.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Prijava na forge nije uspjela. Provjerite token: treba mu pravo čitanja repozitorija i pisanja za spremanje.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Nije pronađeno u repozitoriju — ili ga vaš token ne smije vidjeti.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge je vratio pogrešku. Pokušajte ponovno kasnije.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Ova adresa ne odgovara kao forge. Je li vrsta forgea u Postavke → Pohrana točna?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Najprije postavite WebDAV poslužitelj u Postavke → Pohrana.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Potrebno kada forge radi na privatnoj ili kućnoj mreži. Bez ove oznake sigurnosna provjera odbija privatnu adresu.',
  'Vul server-URL, eigenaar en repository in':
      'Ispunite URL poslužitelja, vlasnika i repozitorij',
  'de standaardbranch heet': 'zadana grana zove se',
  'die wordt voortaan gebruikt': 'ona će se odsad koristiti',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repozitorij je još prazan; prvo spremanje će ga popuniti',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'napomena: ovaj token smije samo čitati, pa spremanje neće uspjeti',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Prijava nije uspjela — provjerite token. Treba mu pravo čitanja repozitorija i pisanja da bi mogao spremati.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repozitorij nije pronađen — ili ga vaš token ne smije vidjeti. Provjerite vlasnika i naziv repozitorija.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Ova adresa ne odgovara kao forge. Je li vrsta forgea koju ste odabrali točna?',
  'kenteken': 'registarska oznaka',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Za jezik ove prezentacije ne postoji popis ključnih riječi za posebne kategorije osobnih podataka. Uzorci s kontrolnom znamenkom (OIB, IBAN, putovnica) rade; riječi poput "dijagnoza" ili "osumnjičenik" ne prepoznaju se.',
  'Landpakketten voor identificatienummers':
      'Paketi država za identifikacijske brojeve',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Brojevi poput nizozemskog BSN-a ili poljskog PESEL-a vezani su uz državu. Cijela Europa je uključena jer većina tih brojeva ima kontrolnu znamenku: njihovo uključivanje gotovo ne košta lažnih upozorenja. IBAN, e-pošta, tajne i putovnički redci od toga su neovisni i uvijek se provjeravaju.',
  'strafrechtelijk gegeven (verdachte)': 'kaznenopravni podatak (osumnjičenik)',
